   internal Context NewContext(){return new Context{Snapshot=Clone(Snapshot),Listing=Clone(Listing)};}
   internal void Intersection(int[][] primary,int[][] secondary){var roles=new List<Dictionary<string,object>>();foreach(var keys in new[]{primary,secondary}){string setId=Guid.NewGuid().ToString("N");var set=new Dictionary<string,object>{{"inspectionRequestId",SourceId},{"inspectionSha256",Program.Hash(ProofPaths[0])},{"expiresUtc",Plan["expiresUtc"]},{"entityKeys",keys}};string sha=NativeJournal.Freeze(Path.Combine(Root,"entitysets",setId+".json"),set);roles.Add(new Dictionary<string,object>(set){{"entitySetId",setId},{"entitySetSha256",sha}});}Plan["entitySets"]=roles.ToArray();Plan["operation"]="intersect_entity_sets";Plan["parameters"]=new Dictionary<string,object>{{"offset",0}};SavePlan();}
   internal void SavePlan(){string path=Path.Combine(Root,"operationplans",PlanId+".json");if(File.Exists(path))File.Delete(path);string sha=NativeJournal.Freeze(path,Plan);Parameters["operationPlanSha256"]=sha;string folder=Path.Combine(Root,"operations",PlanId);if(Directory.Exists(folder)){File.Delete(Path.Combine(folder,"000000.json"));Directory.Delete(folder);}new NativeJournal(Root,PlanId,sha).Append("prepared",new Dictionary<string,object>{{"executionEnabled",false}});}
   internal Dictionary<string,object> Prepare(Context context=null){return OwnedOperationPlans.InContext(Root,Guid.NewGuid().ToString("N"),Parameters,true,context??NewContext());}
