  internal static int Run() {
   int count=0;Action<bool> check=ok=>{if(!ok)throw new Exception("Owned operation self-test failed at "+count);count++;};Action<Action> rejects=action=>{bool denied=false;try{action();}catch(ArgumentException){denied=true;}catch(IOException){denied=true;}catch(InvalidOperationException){denied=true;}catch(UnauthorizedAccessException){denied=true;}check(denied);};
   var f=new Fixture();var ctx=f.NewContext();ctx.DuringRead=n=>{if(n==1)foreach(string path in f.ProofPaths)rejects(()=>File.AppendAllText(path,"tamper"));};var prepared=f.Prepare(ctx);check(Equals(prepared["state"],"owned_operation_prepared_observed")&&ctx.Reads==4&&Equals(prepared["executionEnabled"],false));check(Equals(prepared["guardPasses"],2)&&Equals(prepared["journalPreparedOnly"],true));
   var handle=new Dictionary<string,object>{{"ownedOperationId",prepared["ownedOperationId"]},{"ownedOperationSha256",prepared["ownedOperationSha256"]}};string packetPath=Path.Combine(f.Root,"ownedoperations",(string)prepared["ownedOperationId"]+".json");string eventPath=Path.Combine(f.Root,"operations",(string)prepared["ownedOperationId"],"000000.json");string eventHash=Program.Hash(eventPath);ctx=f.NewContext();ctx.DuringRead=n=>{if(n==3){rejects(()=>File.Delete(packetPath));rejects(()=>File.AppendAllText(eventPath,"tamper"));rejects(()=>File.Delete(f.Working));}};var valid=OwnedOperationPlans.InContext(f.Root,Guid.NewGuid().ToString("N"),handle,false,ctx);check(Equals(valid["state"],"owned_operation_validated_observed")&&ctx.Reads==4&&Program.Hash(eventPath)==eventHash);check(Directory.GetFiles(Path.GetDirectoryName(eventPath),"*.json").Length==1);
   using(var proofs=new OwnedOperationPlans.Proofs()){proofs.Json(f.ProofPaths[0],Program.Hash(f.ProofPaths[0]));rejects(()=>proofs.Json(f.ProofPaths[0],new string('f',64)));}
   foreach(string field in new[]{"model","processId","contextBefore","selectionAfter","lengthUnitFactorRaw","entities"}){var switched=f.NewContext();switched.DuringRead=n=>{if(n==4)switched.Snapshot[field]=field=="model"?(object)new Dictionary<string,object>{{"id",10},{"name","Other"},{"path",f.Working}}:field=="contextBefore"||field=="selectionAfter"||field=="entities"?(object)new[]{1}:2;};check(Equals(f.Prepare(switched)["state"],"owned_operation_rejected"));}
   ctx=f.NewContext();ctx.DuringRead=n=>{if(n==3)ctx.Changed=true;};check(Equals(f.Prepare(ctx)["state"],"owned_operation_rejected"));ctx=f.NewContext();ctx.Listing["windowCount"]=2;check(Equals(f.Prepare(ctx)["state"],"owned_operation_rejected")&&ctx.Reads==0);
