   foreach(string field in new[]{"executionEnabled","sourceIdentity","lengthUnitsRaw","requiredBeforeExecution","expiresUtc"}){var other=new Fixture();other.Plan[field]=field=="executionEnabled"?(object)true:field=="expiresUtc"?(object)DateTime.UtcNow.AddSeconds(-1).ToString("o"):field=="sourceIdentity"?(object)new Dictionary<string,object>():field=="requiredBeforeExecution"?(object)new string[0]:"mm";other.SavePlan();check(Equals(other.Prepare()["state"],"owned_operation_rejected"));}
   var interrupted=new Fixture();File.WriteAllText(Path.Combine(interrupted.Root,"operations",interrupted.PlanId,"writer.lock"),"interrupted");check(Equals(interrupted.Prepare()["state"],"owned_operation_rejected"));var late=new Fixture();var lateContext=late.NewContext();lateContext.DuringRead=n=>{if(n==3)File.WriteAllText(Path.Combine(late.Root,"operations",late.PlanId,"writer.lock"),"late interrupted writer");};check(Equals(late.Prepare(lateContext)["state"],"owned_operation_rejected"));var args=new Dictionary<string,object>(f.Parameters){{"command","SAVE"}};rejects(()=>OwnedOperationPlans.ValidateParameters(args,true));rejects(()=>OwnedOperationPlans.ValidateParameters(new Dictionary<string,object>{{"ownedOperationId","../escape"},{"ownedOperationSha256",new string('a',64)}},false));
   var intersection=new Fixture();intersection.Intersection(new[]{new[]{40,5}},new[]{new[]{21,8}});check(Equals(intersection.Prepare()["state"],"owned_operation_prepared_observed"));foreach(var pair in new[]{new[]{new[]{new[]{21,8}},new[]{new[]{21,8}}},new[]{new[]{new[]{21,8}},new[]{new[]{40,5}}},new[]{new[]{new[]{59,10}},new[]{new[]{21,8}}}}){var other=new Fixture();other.Intersection(pair[0],pair[1]);check(Equals(other.Prepare()["state"],"owned_operation_rejected"));}
